{
    // Lookup table: index i maps to the bit-reversed value of i.
    private static readonly byte[] LookupTable = CreateLookupTable();

    private static byte[] CreateLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int reversed = 0;
            int value = i;
            for (int bit = 0; bit < 8; bit++)
            {
                reversed = (reversed << 1) | (value & 1);
                value >>= 1;
            }
            table[i] = (byte)reversed;
        }
        return table;
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static void ReverseInPlace(Span<byte> data)
    {
        if (Avx2.IsSupported)
        {
            ReverseAvx2(data);
        }
        else if (Ssse3.IsSupported)
        {
            ReverseSsse3(data);
        }
        else if (AdvSimd.IsSupported)
        {
            ReverseNeon(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

